async function attempt(
  llm: LlmGateway,
  candidate: ModelCandidate,
  options: GenerateDraftOptions,
  signal: AbortSignal,
): Promise<string> {
  // prepareCall 时即传入完整 controls（maxTokens/reasoningEffort）。dsh 的 prepared call
  // 在 stream 时会校验这些字段与准备结果完全一致（callConfigEquals），故必须在 prepare 阶段
  // 给齐，不能在 stream 阶段再覆盖（否则抛 INVALID_PREPARED_CALL）。
  const call = await llm.prepareCall({
    provider: candidate.provider,
    model: candidate.model,
    maxTokens: options.maxTokens,
    reasoningEffort: candidate.reasoningEffort,
  }, signal)
  const messages = [
    createUserMessage({
      content: [{ type: 'text', text: options.user }],
      source: { kind: 'user' },
    }),
  ]
  // compared 字段直接沿用 call.config（与 prepared 完全一致）；只追加 system/messages/signal
  // （不属于 callConfigEquals 比较范围）。
  const streamOptions = {
    ...(call.config as Record<string, unknown>),
    system: options.system,
    messages,
    signal,
  }
  const assembler = new BlockAssembler()
  for await (const chunk of call.stream(streamOptions)) {
    assembler.push(chunk as Parameters<typeof assembler.push>[0])
  }
  const text = assembler.blocks()
    .filter(block => block.type === 'text')
    .map(block => (block as { text: string }).text)
    .join('')
    .trim()
  if (!text) {
    throw new AiDraftError('EMPTY', `模型 ${candidate.model} 未返回正文。`)
  }
  return text
}

