    //    它既是安全快照的落盘内容，也是中途失败后自动回滚的唯一来源——不回读磁盘，保证回滚源与落盘字节同源、确定性。
    const before = collectBackup(domain)
    const hasData = Object.values(rowsOf(before)).some(rows => rows.length > 0)
